-- placard_303_abre_avalancha.lua
-- Agrega a placard_303.aseprite los frames de "abre", "avalancha" y "abierto".
-- Uso: abri placard_303.aseprite en Aseprite y corre este script
--      (File > Scripts > Open Scripts Folder, copialo ahi, y despues File > Scripts > Rescan).
-- Que hace:
--   1. Agranda el lienzo 16 px a la izquierda y 12 px abajo (para las puertas abiertas y la pila).
--      Tus frames no se mueven respecto del placard.
--   2. Agrega 7 frames al final en una capa nueva "Avalancha".
--   3. Crea los tags abre (tu frame 6 y 7 + 2 nuevos), avalancha y abierto.
-- Se puede deshacer todo con un solo Ctrl+Z.
local spr = app.activeSprite
if not spr then return app.alert("Abri primero placard_303.aseprite.") end
if not spr.filename:lower():find("placard_303") then
  if app.alert{title="Placard 303", text="El sprite activo no es placard_303. ¿Seguir igual?", buttons={"Seguir","Cancelar"}} ~= 1 then return end
end
for _, t in ipairs(spr.tags) do
  if t.name == "avalancha" then return app.alert("Este archivo ya tiene el tag 'avalancha'. No hago nada.") end
end
if spr.colorMode ~= ColorMode.RGB then return app.alert("El sprite tiene que estar en modo RGB.") end
