local function imagen(rows)
  local img = Image(W, H, ColorMode.RGB)
  for y = 1, #rows do
    local r = rows[y]
    for x = 1, #r do
      local c = r:sub(x, x)
      if c ~= "." then img:drawPixel(x - 1, y - 1, COLORES[c]) end
    end
  end
  return img
end

app.transaction("Placard 303: abre + avalancha", function()
  if spr.width ~= W or spr.height ~= H then
    app.command.CanvasSize{ ui = false, left = PAD_L, top = 0, right = 0, bottom = PAD_B }
  end
  if spr.width ~= W or spr.height ~= H then
    error("No pude agrandar el lienzo (quedo en " .. spr.width .. "x" .. spr.height .. ", esperaba " .. W .. "x" .. H .. ").")
  end
  local capa = spr:newLayer()
  capa.name = "Avalancha"
  local primero = #spr.frames + 1
  local rangos = {}
  for i, f in ipairs(FRAMES) do
    local fr = spr:newEmptyFrame(#spr.frames + 1)
    fr.duration = f.ms / 1000
    spr:newCel(capa, fr, imagen(f.rows), Point(0, 0))
    local r = rangos[f.tag]
    if not r then rangos[f.tag] = { desde = fr.frameNumber, hasta = fr.frameNumber }
    else r.hasta = fr.frameNumber end
  end
  -- "abre" empieza en tus frames 6 y 7 (cerrado y la ropa asomando)
  local abre = rangos["abre"]
  if primero >= 8 then abre.desde = 6 end
  for _, nombre in ipairs({ "abre", "avalancha", "abierto" }) do
    local r = rangos[nombre]
    local t = spr:newTag(r.desde, r.hasta)
    t.name = nombre
    t.aniDir = AniDir.FORWARD
    t.repeats = (nombre == "abierto") and 0 or 1
  end
end)
app.refresh()
app.alert("Listo: abre, avalancha y abierto. Lienzo " .. W .. "x" .. H .. ". Guarda con Ctrl+S.")
